/*
 * Built for Kinetic from scratch after the public preview of BoardUI's "Calendar" (boardui.com/templates/calendar).
 * No BoardUI source was used.
 */
"use client";

import { useRef, useState, type MouseEvent } from "react";
import { CalendarDate, isSameDay, startOfMonth, startOfWeek, toCalendarDate } from "@internationalized/date";
import { RiAddLine, RiArrowLeftLine, RiArrowLeftSLine, RiArrowRightSLine, RiCalendarLine } from "@remixicon/react";

import { DASHBOARD_NAV, DashboardSidebar } from "@/components/motion/dashboard-sidebar";
import { DashboardPageHeader } from "@/components/motion/dashboard-page-header";
import { NotificationBellBadge, type BellNotification } from "@/components/motion/notification-bell-badge";
import { SegmentedControl, SegmentedControlItem } from "@/components/motion/segmented-control";
import { Popover } from "@/components/motion/popover";
import { Button } from "@/components/motion/button";
import { Toaster, toast } from "@/components/motion/toast";
import type { CalendarEvent } from "@/components/motion/calendar-event-chip";
import { cx } from "@/lib/cx";
import {
  CALENDAR_EVENTS,
  CALENDAR_INVITES,
  CALENDAR_NOTIFICATIONS,
  EventDetails,
  InvitesPopover,
  ME_EMAIL,
  NOW,
  NewEventDialog,
  TODAY,
  longDay,
  monthName,
  shortMonth,
  weekdayName,
  type CalendarInvite,
  type CalendarView,
  type NewEventDraft,
  type RsvpStatus,
} from "@/components/motion/calendar-template-parts";
import { DayRail, MonthGrid, TimeGrid } from "@/components/motion/calendar-template-views";

export type { CalendarView } from "@/components/motion/calendar-template-parts";

const HOME_VIEW = "calendar";
const VIEWS: { id: CalendarView; label: string }[] = [
  { id: "day", label: "Day" },
  { id: "week", label: "Week" },
  { id: "month", label: "Month" },
];
const STEPPER_BUTTON =
  "flex size-8 items-center justify-center rounded-md text-foreground-icon-secondary outline-none transition-colors duration-150 ease-out hover:bg-background-secondary-default focus-visible:ring-2 focus-visible:ring-border-focus-ring motion-reduce:transition-none";

// #region critical
/** Sunday-first weeks, as the month grid and week view draw them. */
const LOCALE = "en-US";

/** Six full weeks starting on the Sunday on or before the 1st, so the grid never changes height. */
export function monthWeeks(anchor: CalendarDate): CalendarDate[][] {
  const first = startOfWeek(startOfMonth(anchor), LOCALE);
  return Array.from({ length: 6 }, (_, w) => Array.from({ length: 7 }, (_, d) => first.add({ days: w * 7 + d })));
}

export function weekDays(anchor: CalendarDate): CalendarDate[] {
  const first = startOfWeek(anchor, LOCALE);
  return Array.from({ length: 7 }, (_, d) => first.add({ days: d }));
}

/** One step of the stepper. Month steps clamp the day (31 Aug -> 30 Sep). */
export function stepAnchor(view: CalendarView, anchor: CalendarDate, dir: 1 | -1): CalendarDate {
  if (view === "month") return anchor.add({ months: dir });
  if (view === "week") return anchor.add({ weeks: dir });
  return anchor.add({ days: dir });
}

/** "August 2026" · "16 – 22 Aug 2026" · "30 Aug – 5 Sep 2026" · "Thursday, 20 Aug 2026" */
export function rangeLabel(view: CalendarView, anchor: CalendarDate): string {
  if (view === "month") return `${monthName(anchor)} ${anchor.year}`;
  if (view === "day") return `${weekdayName(anchor)}, ${anchor.day} ${shortMonth(anchor)} ${anchor.year}`;
  const days = weekDays(anchor);
  const a = days[0] ?? anchor;
  const b = days[6] ?? anchor;
  if (a.year !== b.year) return `${a.day} ${shortMonth(a)} ${a.year} – ${b.day} ${shortMonth(b)} ${b.year}`;
  if (a.month !== b.month) return `${a.day} ${shortMonth(a)} – ${b.day} ${shortMonth(b)} ${b.year}`;
  return `${a.day} – ${b.day} ${shortMonth(b)} ${b.year}`;
}
// #endregion

export interface CalendarTemplateProps {
  /** Events on the calendar. Creating, accepting and deleting change a local copy. */
  events?: CalendarEvent[];
  invites?: CalendarInvite[];
  defaultNotifications?: BellNotification[];
  defaultCalendarView?: CalendarView;
  /** Day the calendar opens on, and the day marked as today. */
  today?: CalendarDate;
  /** Sidebar key shown first. Any key other than "calendar" shows a placeholder. */
  defaultView?: string;
  className?: string;
}

export function CalendarTemplate({
  events: initialEvents = CALENDAR_EVENTS,
  invites: initialInvites = CALENDAR_INVITES,
  defaultNotifications = CALENDAR_NOTIFICATIONS,
  defaultCalendarView = "month",
  today = TODAY,
  defaultView = HOME_VIEW,
  className,
}: CalendarTemplateProps) {
  const [view, setView] = useState(defaultView);
  const [calView, setCalView] = useState<CalendarView>(defaultCalendarView);
  const [anchor, setAnchor] = useState<CalendarDate>(today);
  const [events, setEvents] = useState(initialEvents);
  const [invites, setInvites] = useState(initialInvites);
  const [notifications, setNotifications] = useState(defaultNotifications);
  const [openId, setOpenId] = useState<string | null>(null);
  const [newOpen, setNewOpen] = useState(false);
  const [draft, setDraft] = useState<NewEventDraft>({ date: today, hour: 9 });
  const [draftKey, setDraftKey] = useState(0);
  const anchorRef = useRef<HTMLElement | null>(null);
  const counter = useRef(0);

  const navItem = DASHBOARD_NAV.find((item) => item.key === view);
  const isHome = view === HOME_VIEW;
  const openEvent = events.find((e) => e.id === openId) ?? null;

  const onNavClickCapture = (event: MouseEvent<HTMLDivElement>) => {
    if (!(event.target instanceof Element)) return;
    const link = event.target.closest('a[href="#"]');
    if (!link) return;
    event.preventDefault();
    const item = DASHBOARD_NAV.find((entry) => entry.label === link.getAttribute("aria-label"));
    if (item) setView(item.key);
  };

  // The popover anchors to whichever chip, block or agenda row was pressed.
  const pressEvent = (event: CalendarEvent, target: HTMLElement) => {
    anchorRef.current = target;
    setOpenId(event.id);
  };

  const openDay = (date: CalendarDate) => {
    setAnchor(date);
    setCalView("day");
  };

  const startNew = (date: CalendarDate, hour: number) => {
    setDraft({ date, hour });
    setDraftKey((k) => k + 1);
    setNewOpen(true);
  };

  const patchEvent = (id: string, patch: (event: CalendarEvent) => CalendarEvent) =>
    setEvents((list) => list.map((e) => (e.id === id ? patch(e) : e)));

  const createEvent = (input: Omit<CalendarEvent, "id">) => {
    counter.current += 1;
    const created: CalendarEvent = { ...input, id: `new-${counter.current}` };
    const day = toCalendarDate(created.start);
    setEvents((list) => [...list, created]);
    setAnchor(day);
    toast.success("Event created", { description: `${created.title} · ${longDay(day)}` });
  };

  const deleteEvent = (event: CalendarEvent) => {
    setOpenId(null);
    setEvents((list) => list.filter((e) => e.id !== event.id));
    toast("Event deleted", {
      description: event.title,
      actions: [
        {
          label: "Undo",
          onClick: () => setEvents((list) => (list.some((e) => e.id === event.id) ? list : [...list, event])),
        },
      ],
    });
  };

  const rsvp = (event: CalendarEvent, status: RsvpStatus) =>
    patchEvent(event.id, (e) => ({
      ...e,
      attendees: e.attendees?.map((a) => (a.email === ME_EMAIL ? { ...a, status } : a)),
    }));

  const acceptInvite = (id: string) => {
    const invite = invites.find((i) => i.id === id);
    if (!invite) return;
    const event: CalendarEvent = {
      ...invite.event,
      attendees: invite.event.attendees?.map((a) => (a.email === ME_EMAIL ? { ...a, status: "accepted" as const } : a)),
    };
    setInvites((list) => list.filter((i) => i.id !== id));
    setEvents((list) => [...list, event]);
    toast.success("Added to your calendar", { description: `${event.title} · ${longDay(toCalendarDate(event.start))}` });
  };

  const declineInvite = (id: string) => {
    const invite = invites.find((i) => i.id === id);
    setInvites((list) => list.filter((i) => i.id !== id));
    if (invite) toast("Invitation declined", { description: `${invite.from} will be told.` });
  };

  const stepLabel = calView === "month" ? "month" : calView === "week" ? "week" : "day";
  const showsToday = isSameDay(anchor, today);

  return (
    <div
      className={cx("relative flex h-full w-full gap-3 overflow-hidden bg-background-full p-3", className)}
      onClickCapture={onNavClickCapture}
    >
      <DashboardSidebar selected={view} showThemeToggle={false} />

      <main className="flex min-h-0 min-w-0 flex-1 flex-col gap-4 overflow-hidden px-1 pt-1.5">
        <DashboardPageHeader
          title={isHome ? `${monthName(anchor)} ${anchor.year}` : (navItem?.label ?? "Calendar")}
          breadcrumbs={[
            { label: "Acme team", initials: "A", tone: "blue", onPress: () => setView("home") },
            { label: "Jordan", initials: "J", onPress: () => setView("profile") },
            { label: navItem?.label ?? "Calendar", icon: navItem?.icon ?? RiCalendarLine },
          ]}
          dateRange={
            isHome ? (
              <SegmentedControl
                aria-label="Calendar view"
                selectedKeys={[calView]}
                onSelectionChange={(keys) => {
                  const next = VIEWS.find((v) => keys.has(v.id));
                  if (next) setCalView(next.id);
                }}
              >
                {VIEWS.map((v) => (
                  <SegmentedControlItem key={v.id} id={v.id}>
                    {v.label}
                  </SegmentedControlItem>
                ))}
              </SegmentedControl>
            ) : undefined
          }
          notifications={
            <NotificationBellBadge notifications={notifications} onNotificationsChange={(next) => setNotifications([...next])} />
          }
          actions={
            isHome ? (
              <>
                <InvitesPopover invites={invites} onAccept={acceptInvite} onDecline={declineInvite} />
                <Button
                  variant="secondary"
                  disabled={showsToday}
                  title={showsToday ? "Already on today" : undefined}
                  onClick={() => setAnchor(today)}
                >
                  Today
                </Button>
                <div className="flex h-9 items-center gap-0.5 rounded-lg border border-border-button-default bg-background-primary-default px-0.5 shadow-xs">
                  <button
                    type="button"
                    aria-label={`Previous ${stepLabel}`}
                    className={STEPPER_BUTTON}
                    onClick={() => setAnchor((a) => stepAnchor(calView, a, -1))}
                  >
                    <RiArrowLeftSLine className="size-5" aria-hidden />
                  </button>
                  <span aria-live="polite" className="min-w-[164px] px-1 text-center text-body-2-medium text-text-primary tabular-nums">
                    {rangeLabel(calView, anchor)}
                  </span>
                  <button
                    type="button"
                    aria-label={`Next ${stepLabel}`}
                    className={STEPPER_BUTTON}
                    onClick={() => setAnchor((a) => stepAnchor(calView, a, 1))}
                  >
                    <RiArrowRightSLine className="size-5" aria-hidden />
                  </button>
                </div>
                <Button leadingIcon={RiAddLine} onClick={() => startNew(anchor, 9)}>
                  New event
                </Button>
              </>
            ) : undefined
          }
        />

        {isHome ? (
          <div className="mb-3 flex min-h-0 flex-1 gap-3">
            {calView === "month" ? (
              <MonthGrid
                weeks={monthWeeks(anchor)}
                month={anchor}
                events={events}
                today={today}
                selectedId={openId}
                onEventPress={pressEvent}
                onDayOpen={openDay}
                onCreate={startNew}
              />
            ) : (
              <>
                <TimeGrid
                  key={calView}
                  days={calView === "week" ? weekDays(anchor) : [anchor]}
                  events={events}
                  today={today}
                  now={NOW}
                  selectedId={openId}
                  onEventPress={pressEvent}
                  onDayOpen={openDay}
                  onCreate={startNew}
                />
                {calView === "day" ? (
                  <DayRail date={anchor} events={events} selectedId={openId} onDateChange={setAnchor} onEventPress={pressEvent} />
                ) : null}
              </>
            )}
          </div>
        ) : (
          <section
            aria-label={navItem?.label ?? view}
            className="mb-3 flex min-h-0 flex-1 flex-col items-center justify-center gap-4 rounded-2xl border border-dashed border-border-button-default bg-background-secondary-default p-10 text-center"
          >
            <span className="flex size-12 items-center justify-center rounded-full bg-background-primary-default text-foreground-icon-secondary shadow-xs">
              {navItem ? <navItem.icon className="size-6" aria-hidden /> : <RiCalendarLine className="size-6" aria-hidden />}
            </span>
            <div className="flex max-w-sm flex-col gap-1">
              <h2 className="text-title-3-medium text-text-primary">{navItem?.label ?? view}</h2>
              <p className="text-body-regular text-text-secondary">
                {navItem?.label ?? "This view"} is a template of its own. This page is the calendar, so there is nothing to show here yet.
              </p>
            </div>
            <Button variant="secondary" leadingIcon={RiArrowLeftLine} onClick={() => setView(HOME_VIEW)}>
              Back to Calendar
            </Button>
          </section>
        )}
      </main>

      <Popover
        triggerRef={anchorRef}
        isOpen={openEvent != null && isHome}
        onOpenChange={(open) => {
          if (!open) setOpenId(null);
        }}
        placement="end top"
        aria-label={openEvent?.title ?? "Event"}
        className="w-[340px]"
        dialogClassName="flex flex-col gap-3 p-3"
      >
        {openEvent ? (
          <EventDetails
            event={openEvent}
            onRsvp={(status) => rsvp(openEvent, status)}
            onJoin={() => {
              setOpenId(null);
              toast.info(`Joining ${openEvent.title}`, { description: `Meeting code ${openEvent.meetingCode ?? ""}` });
            }}
            onCopyCode={() => {
              const code = openEvent.meetingCode ?? "";
              navigator.clipboard?.writeText(code).catch(() => {});
              toast.success("Meeting code copied", { description: code });
            }}
            onDelete={() => deleteEvent(openEvent)}
          />
        ) : null}
      </Popover>
      <NewEventDialog key={draftKey} isOpen={newOpen} onOpenChange={setNewOpen} draft={draft} onCreate={createEvent} />
      <Toaster position="bottom-end" />
    </div>
  );
}

/*
 * Built for Kinetic from scratch after the public preview of BoardUI's "Calendar" (boardui.com/templates/calendar).
 * No BoardUI source was used.
 */
"use client";

import { useEffect, useRef } from "react";
import { isSameDay, toCalendarDate, type CalendarDate } from "@internationalized/date";

import { CalendarEventChip, calendarEventColorStyles, type CalendarEvent } from "@/components/motion/calendar-event-chip";
import { DateCalendar } from "@/components/motion/date-calendar";
import { cx } from "@/lib/cx";
import { WEEKDAYS, eventsOn, longDay, monthName, pad2, shortMonth, timeRange, weekdayName } from "@/components/motion/calendar-template-parts";

export type EventPress = (event: CalendarEvent, target: HTMLElement) => void;

const DAY_NUMBER =
  "pointer-events-auto flex h-6 min-w-6 items-center justify-center rounded-full px-1.5 text-caption-1-medium tabular-nums outline-none transition-colors duration-150 ease-out focus-visible:ring-2 focus-visible:ring-border-focus-ring motion-reduce:transition-none";

/* ------------------------------------------------------------------ month */

export interface MonthGridProps {
  /** Six rows of seven days, Sunday first. */
  weeks: readonly (readonly CalendarDate[])[];
  /** The month being shown; other days are dimmed. */
  month: CalendarDate;
  events: readonly CalendarEvent[];
  today: CalendarDate;
  selectedId: string | null;
  onEventPress: EventPress;
  onDayOpen: (date: CalendarDate) => void;
  onCreate: (date: CalendarDate, hour: number) => void;
}

export function MonthGrid({ weeks, month, events, today, selectedId, onEventPress, onDayOpen, onCreate }: MonthGridProps) {
  return (
    <div className="grid min-h-0 flex-1 grid-cols-7 grid-rows-[auto_repeat(6,minmax(0,1fr))] gap-px overflow-hidden rounded-2xl border border-separator-border bg-separator-border">
      {WEEKDAYS.map((name) => (
        <div
          key={name}
          className="bg-background-primary-default px-2.5 py-2 text-caption-1-medium text-text-tertiary dark:bg-background-secondary-default"
        >
          <abbr title={name} className="no-underline">
            {name.slice(0, 3)}
          </abbr>
        </div>
      ))}
      {weeks.flat().map((date) => {
        const inMonth = date.month === month.month;
        const isToday = isSameDay(date, today);
        const list = eventsOn(events, date);
        // Three fit a cell; a fourth turns the third slot into "+N more".
        const shown = list.length <= 3 ? list : list.slice(0, 2);
        const hidden = list.length - shown.length;
        return (
          <div
            key={date.toString()}
            data-date={date.toString()}
            className={cx(
              "relative flex min-h-0 flex-col gap-1 overflow-hidden p-1.5",
              inMonth ? "bg-background-primary-default dark:bg-background-secondary-default" : "bg-background-tertiary-default dark:bg-background-full",
            )}
          >
            {/* The cell itself: a click on empty space starts an event on that day. */}
            <button
              type="button"
              tabIndex={-1}
              aria-label={`New event on ${longDay(date)}`}
              onClick={() => onCreate(date, 9)}
              className="absolute inset-0 cursor-default outline-none"
            />
            <div className="pointer-events-none relative flex">
              <button
                type="button"
                aria-label={`${longDay(date)}, ${list.length} events. Open day`}
                aria-current={isToday ? "date" : undefined}
                onClick={() => onDayOpen(date)}
                className={cx(
                  DAY_NUMBER,
                  isToday
                    ? "bg-blue-500 text-text-white"
                    : inMonth
                      ? "text-text-primary hover:bg-background-secondary-hover"
                      : "text-text-tertiary hover:bg-background-quaternary-default",
                )}
              >
                {date.day === 1 ? `${shortMonth(date)} 1` : date.day}
              </button>
            </div>
            <div className="pointer-events-none relative mt-auto flex min-w-0 flex-col gap-0.5">
              {shown.map((event) => (
                <CalendarEventChip
                  key={event.id}
                  title={event.title}
                  color={event.color}
                  start={event.start}
                  allDay={event.allDay}
                  selected={event.id === selectedId}
                  aria-haspopup="dialog"
                  className="pointer-events-auto"
                  onClick={(e) => onEventPress(event, e.currentTarget)}
                />
              ))}
              {hidden > 0 ? (
                <button
                  type="button"
                  onClick={() => onDayOpen(date)}
                  className="pointer-events-auto self-start rounded-md px-1.5 text-caption-1-medium text-text-secondary outline-none hover:text-text-primary focus-visible:ring-2 focus-visible:ring-border-focus-ring"
                >
                  +{hidden} more
                </button>
              ) : null}
            </div>
          </div>
        );
      })}
    </div>
  );
}

/* ------------------------------------------------------------- time grid */

export const HOUR_PX = 48;
const HOURS = Array.from({ length: 24 }, (_, h) => h);
/** Shortest drawn block, so a 15-minute event still has a readable title. */
const MIN_BLOCK_MIN = 28;

interface Placed {
  event: CalendarEvent;
  col: number;
  cols: number;
}

const minutesOf = (t: { hour: number; minute: number }) => t.hour * 60 + t.minute;

/**
 * Side-by-side columns for overlapping events. Events are walked in start
 * order; a run of mutually reachable overlaps forms a cluster, each event
 * takes the first column whose last block has ended, and every event in the
 * cluster shares the cluster's column count.
 */
export function layoutDay(timed: readonly CalendarEvent[]): Placed[] {
  const sorted = [...timed].sort((a, b) => a.start.compare(b.start) || b.end.compare(a.end));
  const placed: Placed[] = [];
  let cluster: Placed[] = [];
  let columnEnds: number[] = [];
  let clusterEnd = -1;
  const flush = () => {
    for (const p of cluster) p.cols = columnEnds.length;
    cluster = [];
    columnEnds = [];
  };
  for (const event of sorted) {
    const start = minutesOf(event.start);
    const end = Math.max(minutesOf(event.end), start + MIN_BLOCK_MIN);
    if (start >= clusterEnd) flush();
    let col = columnEnds.findIndex((e) => e <= start);
    if (col === -1) {
      col = columnEnds.length;
      columnEnds.push(end);
    } else columnEnds[col] = end;
    const p = { event, col, cols: 1 };
    cluster.push(p);
    placed.push(p);
    clusterEnd = Math.max(clusterEnd, end);
  }
  flush();
  return placed;
}

export interface TimeGridProps {
  days: readonly CalendarDate[];
  events: readonly CalendarEvent[];
  today: CalendarDate;
  now: { hour: number; minute: number };
  selectedId: string | null;
  onEventPress: EventPress;
  onDayOpen: (date: CalendarDate) => void;
  onCreate: (date: CalendarDate, hour: number) => void;
  /** Hour scrolled to the top on mount. */
  startHour?: number;
}

export function TimeGrid({ days, events, today, now, selectedId, onEventPress, onDayOpen, onCreate, startHour = 7 }: TimeGridProps) {
  const scrollRef = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = startHour * HOUR_PX - 10;
  }, [startHour]);

  const single = days.length === 1;
  return (
    <div className="flex min-h-0 min-w-0 flex-1 flex-col overflow-hidden rounded-2xl border border-separator-border bg-background-primary-default dark:bg-background-secondary-default">
      <div className="flex border-b border-separator-border">
        <div className="w-14 shrink-0" />
        {days.map((date) => {
          const isToday = isSameDay(date, today);
          return (
            <div
              key={date.toString()}
              className={cx(
                "flex min-w-0 flex-1 items-center gap-1.5 border-s border-separator-border px-2 py-2",
                single ? "justify-start" : "justify-center",
              )}
            >
              <span className="text-caption-1-medium text-text-tertiary">{weekdayName(date).slice(0, 3)}</span>
              <button
                type="button"
                aria-label={`${longDay(date)}. Open day`}
                aria-current={isToday ? "date" : undefined}
                onClick={() => onDayOpen(date)}
                disabled={single}
                className={cx(
                  DAY_NUMBER,
                  "h-7 min-w-7 text-body-2-medium disabled:cursor-default",
                  isToday ? "bg-blue-500 text-text-white" : "text-text-primary enabled:hover:bg-background-secondary-hover",
                )}
              >
                {date.day}
              </button>
            </div>
          );
        })}
      </div>

      <div className="flex border-b border-separator-border">
        <div className="flex w-14 shrink-0 items-center justify-end pe-2 text-caption-2-medium text-text-tertiary">All day</div>
        {days.map((date) => (
          <div key={date.toString()} className="flex min-h-8 min-w-0 flex-1 flex-col gap-0.5 border-s border-separator-border p-1">
            {eventsOn(events, date)
              .filter((e) => e.allDay)
              .map((event) => (
                <CalendarEventChip
                  key={event.id}
                  title={event.title}
                  color={event.color}
                  allDay
                  selected={event.id === selectedId}
                  aria-haspopup="dialog"
                  onClick={(e) => onEventPress(event, e.currentTarget)}
                />
              ))}
          </div>
        ))}
      </div>

      <div ref={scrollRef} className="min-h-0 flex-1 overflow-y-auto overscroll-contain" data-testid="time-grid-scroll">
        <div className="relative flex" style={{ height: 24 * HOUR_PX }}>
          <div className="relative w-14 shrink-0" aria-hidden>
            {HOURS.slice(1).map((h) => (
              <span
                key={h}
                className="absolute end-2 -translate-y-1/2 text-caption-2-regular text-text-tertiary tabular-nums"
                style={{ top: h * HOUR_PX }}
              >
                {pad2(h)}:00
              </span>
            ))}
          </div>
          {days.map((date) => {
            const timed = eventsOn(events, date).filter((e) => !e.allDay && isSameDay(toCalendarDate(e.start), date));
            const isToday = isSameDay(date, today);
            return (
              <div key={date.toString()} className="relative min-w-0 flex-1 border-s border-separator-border" data-day={date.toString()}>
                {HOURS.map((h) => (
                  <button
                    key={h}
                    type="button"
                    tabIndex={-1}
                    aria-label={`New event, ${longDay(date)} at ${pad2(h)}:00`}
                    onClick={() => onCreate(date, h)}
                    className={cx(
                      "absolute inset-x-0 cursor-default outline-none transition-colors duration-100 ease-out hover:bg-background-secondary-default motion-reduce:transition-none dark:hover:bg-background-primary-default",
                      h > 0 && "border-t border-separator-border",
                    )}
                    style={{ top: h * HOUR_PX, height: HOUR_PX }}
                  />
                ))}
                {layoutDay(timed).map(({ event, col, cols }) => {
                  const start = minutesOf(event.start);
                  const length = Math.max(minutesOf(event.end) - start, MIN_BLOCK_MIN);
                  return (
                    <div
                      key={event.id}
                      className="absolute px-0.5 pb-px"
                      style={{
                        top: (start / 60) * HOUR_PX,
                        height: (length / 60) * HOUR_PX,
                        insetInlineStart: `${(col / cols) * 100}%`,
                        width: `${100 / cols}%`,
                      }}
                    >
                      {/* Under 55 minutes there is no room for two lines: one-line chip stretched to the block. */}
                      <CalendarEventChip
                        variant={length < 55 ? "compact" : "full"}
                        style={length < 55 ? { height: "100%" } : undefined}
                        title={event.title}
                        color={event.color}
                        start={event.start}
                        end={event.end}
                        selected={event.id === selectedId}
                        aria-haspopup="dialog"
                        onClick={(e) => onEventPress(event, e.currentTarget)}
                      />
                    </div>
                  );
                })}
                {isToday ? (
                  <div
                    aria-hidden
                    className="pointer-events-none absolute inset-x-0 z-10 flex items-center"
                    style={{ top: (minutesOf(now) / 60) * HOUR_PX }}
                  >
                    <span className="-ms-1 size-2 -translate-y-px rounded-full bg-red-500" />
                    <span className="h-0.5 flex-1 -translate-y-px bg-red-500" />
                  </div>
                ) : null}
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

